class TxWriteRequest {
    
    ///In the currency of the account on the amount side (see `amountSide`).
    final String amount;
    final String? billId;
    final String? budgetId;
    final String? category;
    final String date;
    final String description;
    final AccountInput destination;
    
    ///The amount in another currency: the received amount of a cross-currency transfer, or
    ///"other currency" on expenses/income.
    final String? foreignAmount;
    final String? foreignCurrency;
    final String? notes;
    final AccountInput source;
    final List<String> tags;
    
    ///`HH:mm` in the user's timezone; `null` keeps the old behaviour (noon, or the stored time
    ///when the day is unchanged).
    final String? time;

    TxWriteRequest({
        required this.amount,
        required this.billId,
        required this.budgetId,
        required this.category,
        required this.date,
        required this.description,
        required this.destination,
        required this.foreignAmount,
        required this.foreignCurrency,
        required this.notes,
        required this.source,
        required this.tags,
        required this.time,
    });

    factory TxWriteRequest.fromRawJson(String str) => TxWriteRequest.fromJson(json.decode(str));

    String toRawJson() => json.encode(toJson());

    factory TxWriteRequest.fromJson(Map<String, dynamic> json) => TxWriteRequest(
        amount: json["amount"],
        billId: json["billId"],
        budgetId: json["budgetId"],
        category: json["category"],
        date: json["date"],
        description: json["description"],
        destination: AccountInput.fromJson(json["destination"]),
        foreignAmount: json["foreignAmount"],
        foreignCurrency: json["foreignCurrency"],
        notes: json["notes"],
        source: AccountInput.fromJson(json["source"]),
        tags: List<String>.from(json["tags"].map((x) => x)),
        time: json["time"],
    );

    Map<String, dynamic> toJson() => {
        "amount": amount,
        "billId": billId,
        "budgetId": budgetId,
        "category": category,
        "date": date,
        "description": description,
        "destination": destination.toJson(),
        "foreignAmount": foreignAmount,
        "foreignCurrency": foreignCurrency,
        "notes": notes,
        "source": source.toJson(),
        "tags": List<dynamic>.from(tags.map((x) => x)),
        "time": time,
    };
}


