        "group": group,
        "name": name,
        "notes": notes,
        "startDate": startDate,
        "targetAmount": targetAmount,
        "targetDate": targetDate,
    };
}

class PiggyAccountAmount {
    final String accountId;
    
    ///Money currently saved in this goal from that account.
    final String currentAmount;

    PiggyAccountAmount({
        required this.accountId,
        required this.currentAmount,
    });

    factory PiggyAccountAmount.fromRawJson(String str) => PiggyAccountAmount.fromJson(json.decode(str));

    String toRawJson() => json.encode(toJson());

    factory PiggyAccountAmount.fromJson(Map<String, dynamic> json) => PiggyAccountAmount(
        accountId: json["accountId"],
        currentAmount: json["currentAmount"],
    );

    Map<String, dynamic> toJson() => {
        "accountId": accountId,
        "currentAmount": currentAmount,
    };
}

class PiggyEditPayload {
    
    ///Always the full list: Firefly syncs the accounts of a goal with it.
    final List<PiggyAccountAmount> accounts;
    final String currency;
    final String? group;
    final String id;
    final String name;
    final String? notes;
    final String? startDate;
    final String? targetAmount;
    final String? targetDate;

    PiggyEditPayload({
        required this.accounts,
        required this.currency,
        required this.group,
        required this.id,
        required this.name,
        required this.notes,
        required this.startDate,
        required this.targetAmount,
        required this.targetDate,
    });

    factory PiggyEditPayload.fromRawJson(String str) => PiggyEditPayload.fromJson(json.decode(str));

    String toRawJson() => json.encode(toJson());

    factory PiggyEditPayload.fromJson(Map<String, dynamic> json) => PiggyEditPayload(
        accounts: List<PiggyAccountAmount>.from(json["accounts"].map((x) => PiggyAccountAmount.fromJson(x))),
        currency: json["currency"],
        group: json["group"],
        id: json["id"],
        name: json["name"],
        notes: json["notes"],
        startDate: json["startDate"],
        targetAmount: json["targetAmount"],
        targetDate: json["targetDate"],
    );

    Map<String, dynamic> toJson() => {
        "accounts": List<dynamic>.from(accounts.map((x) => x.toJson())),
        "currency": currency,
        "group": group,
        "id": id,
        "name": name,
        "notes": notes,
        "startDate": startDate,
        "targetAmount": targetAmount,
        "targetDate": targetDate,
    };
}

class EnumValues<T> {
    Map<String, T> map;
    late Map<T, String> reverseMap;

    EnumValues(this.map);

    Map<T, String> get reverse {
            reverseMap = map.map((k, v) => MapEntry(v, k));
            return reverseMap;
    }
}
